@page "/chat"
@using sv_8524c869c3cf4a0daa7ed9bbeb1eb1ac.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@selectedChannelName"
                 ChannelDescription="@selectedChannelDescription"
                 Messages="messages"
                 ThreadReplyCounts="threadReplyCounts"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages"
                 class="@(activeThreadRootMessage is not null ? "with-thread" : "full-width")" />

    @if (activeThreadRootMessage is not null)
    {
        <ThreadPanel RootMessage="activeThreadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReplySubmit="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<Message> threadReplies = new();
    private Dictionary<int, int> threadReplyCounts = new();
    private Message? activeThreadRootMessage;

    private int selectedChannelId;
    private string selectedChannelName = string.Empty;
    private string selectedChannelDescription = string.Empty;
    private bool isLoadingMore;

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannelId = channel.Id;
        selectedChannelName = channel.Name;
        selectedChannelDescription = channel.Description;

        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);
        await UpdateThreadCounts();

        // Close thread panel when switching channels
        activeThreadRootMessage = null;
        threadReplies = new();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            await UpdateThreadCounts();
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        activeThreadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (activeThreadRootMessage is not null)
        {
            threadReplies = await ChatService.GetThreadAsync(messageId);
        }
    }

    private void CloseThread()
    {
        activeThreadRootMessage = null;
        threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (activeThreadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            selectedChannelId, content, activeThreadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count
        threadReplyCounts[activeThreadRootMessage.Id] =
            threadReplyCounts.GetValueOrDefault(activeThreadRootMessage.Id) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messages.Count);
    }

    private async Task UpdateThreadCounts()
    {
        // Build thread reply counts from messages that have ReplyToId set
        threadReplyCounts = messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        await Task.CompletedTask;
    }
}

