toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
}

::deep .sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #333;
}

::deep .sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    position: relative;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #2c2f33;
}

::deep .channel-item.active {
    background: #2c2f33;
    border-left-color: #4a9eff;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #fff;
}

::deep .channel-description {
    font-size: 0.8rem;
    color: #999;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #e74c3c;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    min-width: 0;
}

::deep .message-area.full-width {
    flex: 1;
}

::deep .message-area.with-thread {
    flex: 0 0 55%;
}

::deep .message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #42454a;
    background: #2f3136;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #999;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 10px;
    color: #72767d;
    font-size: 0.85rem;
}

/* Message Bubble */
::deep .message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
    margin-bottom: 4px;
    transition: background 0.1s;
}

::deep .message-bubble:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.95rem;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #72767d;
}

::deep .message-content {
    font-size: 0.95rem;
    line-height: 1.4;
    word-break: break-word;
}

::deep .message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

::deep .reaction-badge {
    background: #2f3136;
    border: 1px solid #42454a;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #4a4d52;
}

::deep .thread-link {
    color: #4a9eff;
    font-size: 0.8rem;
    cursor: pointer;
    margin-top: 4px;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -10px;
    right: 10px;
    background: #2f3136;
    border: 1px solid #42454a;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

::deep .action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    padding: 4px 8px;
    cursor: pointer;
    font-size: 0.8rem;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background: #42454a;
    color: #fff;
}

::deep .emoji-picker {
    position: absolute;
    top: -10px;
    right: 10px;
    transform: translateY(-100%);
    background: #2f3136;
    border: 1px solid #42454a;
    border-radius: 6px;
    padding: 6px;
    display: flex;
    gap: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

::deep .emoji-option {
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .emoji-option:hover {
    background: #42454a;
}

/* Message Input */
::deep .message-input {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #42454a;
    background: #2f3136;
}

::deep .message-input textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 6px;
    padding: 10px 14px;
    color: #dcddde;
    font-size: 0.95rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-input textarea::placeholder {
    color: #72767d;
}

::deep .btn-send {
    background: #4a9eff;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 10px 18px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background 0.15s;
}

::deep .btn-send:hover:not(:disabled) {
    background: #3a8eef;
}

::deep .btn-send:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    border-left: 1px solid #42454a;
    display: flex;
    flex-direction: column;
    color: #dcddde;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #42454a;
}

::deep .thread-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

::deep .btn-close-thread {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .btn-close-thread:hover {
    background: #42454a;
    color: #fff;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #42454a;
    background: #36393f;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

::deep .thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #3a3d42;
}

::deep .thread-reply:last-child {
    border-bottom: none;
}

